// Source details are shown with results, never beside the voting controls.
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function renderMVMethod({questions,sources,language,showPositions,scoring}){
  const de=language==='de',local=q=>de?q.de:q;
  const names=sources.slice(0,7).map(s=>s[0]);
  const label=p=>p===null?(de?'Unklar · nicht gewertet':'Unknown · excluded'):p===1?(de?'Zustimmung':'Agree'):p===-1?(de?'Ablehnung':'Disagree'):p===0?(de?'Neutral / gemischt':'Neutral / mixed'):(de?'Bedingte Zustimmung':'Qualified agreement');
  return `<details class="method" id="method"><summary>${de?'Über die Thesen, Quellen und Auswertung':'About the statements, sources and scoring'}</summary>
  <p>${de?'Redaktioneller Vergleich zur Landtagswahl Mecklenburg-Vorpommern am 20. September 2026. Stand der Recherche: 14. September 2026. Grundlage sind die Landeswahlprogramme und die veröffentlichten Parteiantworten im Wahl-O-Mat MV 2026. Unsere Formulierungen und Einordnungen sind nicht von den Parteien autorisiert. Keine Verbindung zu Wahl-O-Mat oder einer Partei.':'Editorial comparison for the Mecklenburg-Vorpommern state election on 20 September 2026. Research date: 14 September 2026. Based on state manifestos and published party responses in Wahl-O-Mat MV 2026. Our wording and interpretations are not authorised by the parties. No affiliation with Wahl-O-Mat or any party.'}</p>
  <p>${esc(scoring)}</p>
  <p>${de?'Sieben ausgewählte Parteien, nicht das gesamte Wahlangebot. Gleiche Gewichtung aller beantworteten Thesen; dies ist keine wissenschaftlich validierte Wahlempfehlung. Eine unbekannte Position ist weder Ablehnung noch Neutralität. Vergleiche mit unterschiedlicher Quellenabdeckung sind nur eingeschränkt vergleichbar. Auch eine hohe Prozentzahl ist keine sichere Aussage über die gesamte Politik einer Partei.':'Seven selected parties, not the full ballot. Answered statements have equal weight; this is not a scientifically validated voting recommendation. An unknown position is neither disagreement nor neutrality. Different evidence coverage limits comparability. Even a high percentage is not a reliable assessment of a party’s entire platform.'}</p>
  <p>${de?'Gegenüber dem Entwurf wurden einige Thesen präzisiert. Die bisherigen Fragen zu Schulstandorten, Mittagessen und Rückführungspersonal wurden durch Förderschulen, Handynutzung und Bezahlkarte ersetzt. Alte Ergebnislinks behalten den ursprünglichen Entwurf.':'Several draft statements were refined. The former school-location, school-lunch and return-staff questions were replaced with special schools, phone use and the benefit payment card. Old result links retain the original draft.'}</p>
  <div>${sources.map(([name,url])=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(name)} ↗</a>`).join('')}</div>
  ${showPositions?`<div class="mv-evidence"><h3>${de?'Belege je These und Partei':'Evidence by statement and party'}</h3><p>${de?'Parteieigene Antworten wurden nur bei inhaltlich passender These übernommen. Bei Ferienwohnungen und finanzieller Beteiligung zählt die Begründung, nicht eine schematisch übertragene Antwort. CDU: Bahnreaktivierung nur als Prüfauftrag (0,5). Bei Werftbürgschaften unterstützt das BSW keine Militärprojekte; andere Parteien nennen ebenfalls Bedingungen. Bei Videoüberwachung bedeutet eine ablehnende Antwort nicht zwingend Ablehnung jeder Kamera an einem Kriminalitätsschwerpunkt.':'Party answers are used only where the policy matches. Holiday-let restrictions and local financial benefits use the explanation, not a mechanically transferred answer. CDU railway reactivation is a commitment to review only (0.5). BSW excludes military projects from shipyard guarantees; other parties also state conditions. Opposition to expanding public-space cameras does not necessarily mean opposing every camera at a crime hotspot.'}</p>${questions.map(x=>`<details class="source-topic"><summary>${x.id}. ${esc(local(x).topic)}</summary><p>${esc(local(x).statement)}</p><ul>${names.map((name,i)=>{const e=x.evidenceNotes.find(e=>e.party===i);return `<li><strong>${esc(name)}</strong>: ${label(x.positions[i])}${e?` · <a href="${esc(e.url)}" target="_blank" rel="noopener noreferrer">${esc(e.section)} ↗</a> · ${e.kind==='party-answer'?(de?'Parteiantwort':'Party response'):(de?'Redaktionelle Einordnung':'Editorial interpretation')}`:` · ${de?'Kein hinreichend genauer Beleg für diese Formulierung in den geprüften Quellen.':'No sufficiently specific evidence for this wording in the reviewed sources.'}`}</li>`}).join('')}</ul></details>`).join('')}</div>`:''}</details>`;
}
